look.customCSS:
/* ───── 梅子饭团 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/90px 90px,#F5F2EA !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一整块白米，底边包一条海苔 */
[data-wk="chathead"]{background:url("data:image/svg+xml;base64,") 0 0/40px 30px,#fff !important;border-bottom:6px solid #2C3A33 !important;box-shadow:0 3px 8px rgba(44,58,51,.12) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#2E3530 !important;font-weight:600 !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#9A9D96 !important}
[data-wk="chatback"] svg{stroke:#2C3A33 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-10px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;flex-shrink:0 !important;aspect-ratio:1 !important;border-radius:50% 50% 16% 16% / 66% 66% 34% 34% !important}
[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 3px #fff,0 0 0 4px #E8E4DA,0 4px 0 3px #2C3A33 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img{box-shadow:0 0 0 3px #fff,0 0 0 4px #E8E4DA,0 4px 0 3px #D9474A !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-8px !important;bottom:-5px !important;width:13px !important;height:13px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}

/* 头像：饭团形——上圆下宽，一圈白米，底下垫一弯海苔（我的垫梅子红）， */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% 50% 16% 16% / 66% 66% 34% 34% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] > :first-child[data-wk="avatar"]{box-shadow:0 0 0 4px #fff,0 0 0 5px #E8E4DA,0 5px 0 4px #2C3A33,0 8px 10px rgba(44,58,51,.18) !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"],[data-wk="cardrow"][data-me="1"] [data-wk="avatar"],[data-wk="rpsingle"] > [data-wk="rpcard"] + [data-wk="avatar"]{box-shadow:0 0 0 4px #fff,0 0 0 5px #E8E4DA,0 5px 0 4px #D9474A,0 8px 10px rgba(44,58,51,.18) !important}
[data-wk="msg"]{position:relative !important}

/* 气泡：他是白米饭团、左边包一截海苔；我是整张海苔、右边一颗梅子 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:14px !important;line-height:1.6 !important;letter-spacing:.03em !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(90deg,#2C3A33 0 18px,transparent 18px),url("data:image/svg+xml;base64,") 0 0/40px 30px,#fff !important;color:#2E3530 !important;padding:10px 16px 10px 30px !important;box-shadow:0 2px 0 #E8E4DA,0 4px 10px rgba(44,58,51,.1) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:6px !important;top:8px !important;width:6px !important;height:calc(100% - 16px) !important;background:linear-gradient(180deg,rgba(255,255,255,.12) 0 2px,transparent 2px 8px) 0 0/6px 8px !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(135deg,#3B4B42,#2C3A33) !important;color:#fff !important;padding:10px 38px 10px 16px !important;box-shadow:0 2px 0 #1E2823,0 4px 10px rgba(44,58,51,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:10px !important;top:calc(50% - 9px) !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after,[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:none !important}

/* 时间：一行灰字，两边几粒米 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#9A9D96 !important;font-size:11.5px !important;letter-spacing:.15em !important}
[data-wk="time"] > span::before{content:"· · ·  " !important;color:#E8E4DA !important}
[data-wk="time"] > span::after{content:"  · · ·" !important;color:#E8E4DA !important}
/* 已读：一粒黑芝麻；没读是一粒白米 */
[data-wk="meta"]{color:#9A9D96 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:7px !important;height:4px !important;border-radius:50% !important;background:#2C3A33 !important;transform:rotate(-25deg) !important}
[data-wk="meta"][data-read="0"]::before{background:#fff !important;box-shadow:0 0 0 1px #E8E4DA !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#9A9D96 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#fff !important;border:none !important;border-radius:14px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#2C3A33 !important}

/* 动描：一张浅竹叶绿的小便笺，左边一片竹叶，不跟气泡一个样 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;position:relative !important;background:#EAF3E3 !important;border:none !important;border-radius:4px 12px 12px 4px !important;box-shadow:none !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#5E7A58 !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:5px 14px 5px 30px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:8px !important;top:7px !important;width:16px !important;height:12px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAyMic+PHBhdGggZD0nTTIgMjAgQzYgOCAxNiAyIDI4IDIgQzI1IDEyIDE2IDE5IDIgMjBaJyBmaWxsPScjNkZCMDZBJy8+PHBhdGggZD0nTTMgMTkgQzEwIDEzIDE3IDggMjYgMycgc3Ryb2tlPScjNEU4QzRBJyBzdHJva2Utd2lkdGg9JzEnIGZpbGw9J25vbmUnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="myactink"]{border-radius:12px 4px 4px 12px !important;padding:5px 30px 5px 14px !important;background:#FBE9E6 !important;color:#A0504C !important}
[data-wk="myactink"]::before{left:auto !important;right:8px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;width:12px !important;height:12px !important}
/* 系统提示：一行小灰字，两头一粒芝麻 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9A9D96 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"• " !important;color:#2C3A33 !important}
[data-wk="sysnotetext"]::after{content:" •" !important;color:#2C3A33 !important}
/* 旁白栏 */
[data-wk="narrbar"]{background:#fff !important;border-top:1px solid #E8E4DA !important}
[data-wk="narrkind"]{border:1px solid #E8E4DA !important;border-radius:999px !important;background:transparent !important;color:#9A9D96 !important}
[data-wk="narrkind"][data-on="1"]{background:#2C3A33 !important;border-color:#2C3A33 !important;color:#fff !important}

/* 底栏：一块白米托盘；左竹叶加号、米色输入框、右边梅子发送、小饭团回复 */
[data-wk="composer"]{background:#fff !important;border-top:none !important;box-shadow:0 -3px 10px rgba(44,58,51,.08) !important;align-items:center !important;gap:8px !important;border-radius:18px 18px 0 0 !important}
[data-wk="chatinput"]{background:#F4F2EC !important;border:none !important;border-radius:14px !important;color:#2E3530 !important}
[data-wk="chatinput"]::placeholder{color:#B3B5AE !important}
[data-wk="chatplus"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAzMCc+PHBhdGggZD0nTTQgMjYgQzYgMTIgMTUgNSAyNyAzIEMyNiAxNSAxOCAyNCA0IDI2WicgZmlsbD0nIzZGQjA2QScvPjxwYXRoIGQ9J001IDI1IEMxMSAxOCAxOCAxMSAyNSA1JyBzdHJva2U9JyM0RThDNEEnIHN0cm9rZS13aWR0aD0nMS4yJyBmaWxsPSdub25lJy8+PC9zdmc+") center/contain no-repeat !important;font-size:0 !important;color:transparent !important;padding:0 !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;border:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;opacity:1 !important}
[data-wk="chatreply"]{width:38px !important;min-width:38px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}

/* ───── 梅子饭团 · 第二批：卡片（形状不动；都是一块白米，顶上包一条海苔，底下一点米色厚度） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{position:relative !important;overflow:hidden !important;background:url("data:image/svg+xml;base64,") 0 0/40px 30px,#fff !important;border:none !important;border-top:7px solid #2C3A33 !important;border-radius:14px !important;box-shadow:0 2px 0 #E8E4DA,0 4px 12px rgba(44,58,51,.12) !important;color:#2E3530 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *{color:#2E3530 !important;border-color:#E8E4DA !important}
/* 转账：金额是海苔黑，收下盖一颗梅子章 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#2C3A33 !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:#E8E4DA !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#FAF8F3 !important;border-top:1px solid #E8E4DA !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#2C3A33 !important;color:#fff !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid #E8E4DA !important}
[data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:38px !important;height:38px !important;font-size:0 !important;color:transparent !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-10deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：不是信封——一块梅子红的布巾，左边卧一个小饭团；领完变淡 */
[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(135deg,#E25A5C,#D9474A) !important;border:none !important;border-radius:14px !important;box-shadow:0 2px 0 #B5383B,0 4px 12px rgba(217,71,74,.25) !important;padding-left:56px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:calc(50% - 20px) !important;width:40px !important;height:40px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.7 !important}
[data-wk="rpenvelope"]{background:radial-gradient(circle at 50% 18%,rgba(255,255,255,.25),transparent 55%),linear-gradient(180deg,#E25A5C,#B5383B) !important;border:none !important;border-radius:20px !important;box-shadow:0 12px 30px rgba(0,0,0,.25) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 4px 6px rgba(0,0,0,.25)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#fff !important}
/* 照片：白米框里一块浅米色小屏；语音跟气泡一样 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:10px !important;background:#F1EEE6 !important;border:none !important;box-shadow:none !important;outline:none !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#6E716B !important}
[data-wk="photoface"] svg{stroke:#2C3A33 !important}
[data-wk="voice"][data-me]{background:linear-gradient(90deg,#2C3A33 0 14px,transparent 14px),#fff !important;border:none !important;border-radius:14px !important;padding-left:22px !important;box-shadow:0 2px 0 #E8E4DA !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(135deg,#3B4B42,#2C3A33) !important;padding-left:12px !important;box-shadow:0 2px 0 #1E2823 !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#2E3530 !important}
[data-wk="voice"][data-me="1"] > *{color:#fff !important}
[data-wk="voicewave"] span{background:#2C3A33 !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#fff !important}
/* 天气：白米卡，太阳是一个煎蛋黄；下面那句话垫浅米色 */
[data-wk="wxcard"]{overflow:hidden !important;background:url("data:image/svg+xml;base64,") 0 0/40px 30px,#fff !important;border:none !important;border-top:7px solid #2C3A33 !important;border-radius:14px !important;box-shadow:0 2px 0 #E8E4DA,0 4px 12px rgba(44,58,51,.12) !important}
[data-wk="wxcard"] *{color:#2E3530 !important}
[data-wk="wxcardsky"]{background:transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,#F6C445 0 11px,#fff 12px 17px,transparent 18px) !important}
[data-wk="wxcardsky"] svg{stroke:#2C3A33 !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:#F4F2EC !important;border:none !important}
[data-wk="wxcardsay"]{background:#F7F5EF !important;border-top:1px solid #E8E4DA !important}
[data-wk="wxcardsay"],[data-wk="wxcardsay"] *{color:#2E3530 !important}
[data-wk="geopin"]{background:#D9474A !important;box-shadow:0 0 0 2px #fff !important}
[data-wk="geopinstem"]{background:#2C3A33 !important}
[data-wk="namecard"] img{border-radius:50% 50% 16% 16% / 66% 66% 34% 34% !important;box-shadow:0 0 0 3px #fff,0 3px 0 3px #2C3A33 !important}
/* 卡片下面的已读也是一粒芝麻 */
[data-run][data-last="1"] + [data-wk="cardmeta"]::before{content:"" !important;display:inline-block !important;vertical-align:middle !important;width:7px !important;height:4px !important;border-radius:50% !important;background:#2C3A33 !important;transform:rotate(-25deg) !important;margin:0 6px !important}
/* 拍一拍、通话结束 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;border:none !important;background:#fff !important;border-radius:999px !important;padding:3px 14px !important;color:#9A9D96 !important;box-shadow:0 1px 0 #E8E4DA !important}
[data-wk="note"][data-part="call"] svg{stroke:#9A9D96 !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:#fff !important;border:none !important;border-left:5px solid #2C3A33 !important;border-radius:6px 12px 12px 6px !important;padding:8px 14px !important;color:#6E716B !important;font-size:12px !important;line-height:1.65 !important;text-align:left !important;box-shadow:0 2px 0 #E8E4DA !important}
[data-wk="noteink"]{color:#9A9D96 !important}
[data-wk="callact"]{color:#D9474A !important}
[data-wk="rpavatar"],[data-wk="rpavatar"] *{border-radius:50% 50% 16% 16% / 66% 66% 34% 34% !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 3px #fff,0 3px 0 3px #2C3A33 !important}
/* 线下小结 */
[data-wk="offlogtitle"]{letter-spacing:.15em !important;color:#2C3A33 !important;font-weight:600 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#D9474A !important}
[data-wk="offlogtranscript"]{border-top:1px solid #E8E4DA !important}
/* 加号面板：一颗颗小饭团形的白米扣子，底下垫海苔 */
[data-wk="chatpanel"]{background:#fff !important;border-top:1px solid #E8E4DA !important}
[data-wk="chattoolicon"]{background:#fff !important;border:none !important;border-radius:50% 50% 16% 16% / 66% 66% 34% 34% !important;box-shadow:0 0 0 1px #E8E4DA,0 4px 0 1px #2C3A33 !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#2C3A33 !important;color:#2C3A33 !important}
[data-wk="chattool"]:nth-child(3n+2) [data-wk="chattoolicon"]{box-shadow:0 0 0 1px #E8E4DA,0 4px 0 1px #D9474A !important}
[data-wk="chattoollabel"]{color:#9A9D96 !important}
/* 引用：左边一条海苔 */
[data-wk="quotedraft"]{background:#fff !important;border-top:1px solid #E8E4DA !important}
[data-wk="quote"]{background:#F4F2EC !important;color:#6E716B !important;border:none !important;border-left:4px solid #2C3A33 !important;border-radius:6px !important;opacity:1 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#D9474A !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}
/* 线下：提示键是一块玉子烧，照片键是一个小饭团 */
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"]{width:30px !important;min-width:30px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;font-size:0 !important;color:transparent !important;padding:0 !important}
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"] *{opacity:0 !important}
